org.machanism.machai.mcp.server.CustomServer server = new org.machanism.machai.mcp.server.CustomServer();
org.machanism.macha.core.commons.configurator.Configurator config = obtainConfigurator();
java.lang.String[] enabledTools = server.readEnabledTools(config);

java.io.File projectDir = server.getProjectDir();
if (projectDir != null) {
    java.nio.file.Path workspace = projectDir.toPath();
}

public class CustomServer extends org.machanism.machai.mcp.server.AbstractMcpServer {
    public void configureWorkspace(java.io.File workspace) {
        setProjectDir(workspace);
    }
}

public class ProjectMcpServer extends org.machanism.machai.mcp.server.AbstractMcpServer {
    public void useProject(java.io.File project) {
        setProjectDir(project);
    }
}
